def is_single_quoted_literal(s):
    if len(s) < 2 or s[0] != "'" or s[-1] != "'":
        return False
    inner = s[1:-1]
    i, n = 0, len(inner)
    while i < n:
        c = inner[i]
        if c == "'":
            return False
        if c == '\\':
            if i + 1 >= n or inner[i + 1] not in ('\\', "'"):
                return False
            i += 2
        else:
            i += 1
    return True

