def is_valid_tag_sequence(s):
    import re
    tokens = re.findall(r'</?[a-z]+>|.', s)
    stack = []
    for tok in tokens:
        m_open = re.fullmatch(r'<([a-z]+)>', tok)
        m_close = re.fullmatch(r'</([a-z]+)>', tok)
        if m_open:
            stack.append(m_open.group(1))
        elif m_close:
            if not stack or stack[-1] != m_close.group(1):
                return False
            stack.pop()
        else:
            return False
    return len(stack) == 0

